    print('=====',f.split('/')[-1]); print({k:m[k] for k in ('costoMedioPorPregunta','costoMedioPorPreguntaConLlm','tokensMediosPorPreguntaConLlm','latenciaMs','cumpleUmbrales','preguntasConLlm')}, d['duracionS'])
